contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        require(amount < type(uint).max - 10);

        uint oldPot = c.pot(); if (__ESBMC_reverted()) return;
        uint oldBalance = address(c).balance;
        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint newPot = c.pot(); if (__ESBMC_reverted()) return;
        uint newBalance = address(c).balance;

        assert(
            (amount != 10 && reverted && newPot == oldPot && newBalance == oldBalance) ||
            (amount == 10 && !reverted && newBalance == oldBalance - oldPot && newPot == 0) ||
            (amount == 10 && !reverted && newPot == oldPot + 10 && newBalance == oldBalance + 10)
        );
    }

    receive() external payable {}
}

