pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        vm.assume(amount < type(uint).max - 10);
        uint256 oldPot;
        try c.pot() returns (uint256 __r) { oldPot = __r; } catch { return; }
        uint oldBalance = address(c).balance;
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 newPot;
        try c.pot() returns (uint256 __r) { newPot = __r; } catch { return; }
        uint newBalance = address(c).balance;
        assertTrue((amount != 10 && reverted && newPot == oldPot && newBalance == oldBalance) ||
            (amount == 10 && !reverted && newBalance == oldBalance - oldPot && newPot == 0) ||
            (amount == 10 && !reverted && newPot == oldPot + 10 && newBalance == oldBalance + 10));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
